@lru_cache(maxsize=128)
def fib(n: int) -> int:
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

@timeit
def slow(x):
    return sum(range(x))

class Counter:
    def __init__(self):
        self.n = 0
    def inc(self):
        self.n += 1
    def value(self):
        return self.n

class Stack:
    def __init__(self):
        self._data = []
    def push(self, x):
        self._data.append(x)
    def pop(self):
        return self._data.pop()
    def __len__(self):
        return len(self._data)

def find(xs, target):
    for i, x in enumerate(xs):
        if x == target:
            return i
    return -1

def safe_div(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return 0

def render_dashboard(metrics):
    lines = []
    lines.append('=== Dashboard ===')
    for k, v in metrics.items():
        if isinstance(v, (int, float)):
            lines.append(f'{k:>20}: {v:>10.2f}')
        else:
            lines.append(f'{k:>20}: {v}')
    if 'errors' in metrics and metrics['errors'] > 0:
        lines.append('!! Errors detected; check logs.')
    elif 'warnings' in metrics and metrics['warnings'] > 0:
        lines.append('* Warnings present.')
    else:
        lines.append('OK')
    return '\n'.join(lines)

